css:
.dark-circuit-wrapper {
  min-height: 100%;
  width: 100%;
  position: relative;
  background-color: #0f0f0f;
}

.dark-circuit-background {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 19px,
      rgba(34, 197, 94, 0.15) 19px,
      rgba(34, 197, 94, 0.15) 20px,
      transparent 20px,
      transparent 39px,
      rgba(34, 197, 94, 0.15) 39px,
      rgba(34, 197, 94, 0.15) 40px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 19px,
      rgba(34, 197, 94, 0.15) 19px,
      rgba(34, 197, 94, 0.15) 20px,
      transparent 20px,
      transparent 39px,
      rgba(34, 197, 94, 0.15) 39px,
      rgba(34, 197, 94, 0.15) 40px
    ),
    radial-gradient(
      circle at 20px 20px,
      rgba(16, 185, 129, 0.18) 2px,
      transparent 2px
    ),
    radial-gradient(
      circle at 40px 40px,
      rgba(16, 185, 129, 0.18) 2px,
      transparent 2px
    );
  background-size:
    40px 40px,
    40px 40px,
    40px 40px,
    40px 40px;
}
